/**
 * scoring.ts — Pure scoring algorithm for QuizSnap.
 *
 * All functions are pure (no DB access, no side effects).
 * This file is safe to import from both client and server code.
 *
 * Question types and their scoring behaviour:
 *   multiple-choice       → single answerId, uses answer.score
 *   multiple-choice-multi → answerIds[], sums all selected answer scores
 *   image-choice          → single answerId, uses answer.score
 *   dropdown              → single answerId, uses answer.score
 *   slider                → numeric `value`, used directly as score
 *   rating                → numeric `value`, used directly as score
 *   text-input            → score = 0 (free text, no scoreable value)
 *   email                 → score = 0
 *   date                  → score = 0
 */

// ── Types ─────────────────────────────────────────────────────────────────────

/**
 * A single shopper answer as submitted from the storefront.
 * Exactly one of `answerId`, `answerIds`, or `value` will be populated
 * depending on the question type.
 */
export interface QuizAnswer {
  /** The question this answer belongs to. */
  questionId: string;
  /** For single-choice questions (multiple-choice, image-choice, dropdown). */
  answerId?: string;
  /** For multi-select questions (multiple-choice-multi). */
  answerIds?: string[];
  /** For slider, rating, text-input, email, date questions. */
  value?: string;
}

/**
 * Preloaded answer data from the database, keyed by answer ID.
 * The caller resolves this from the DB before invoking scoring functions.
 */
export interface AnswerData {
  id: string;
  /** The numeric score this answer contributes (Answer.score in DB). */
  score: number;
  /** Product tags attached to this answer (parsed from Answer.productTags JSON). */
  productTags: string[];
}

/**
 * Preloaded result page data from the database.
 */
export interface ResultPageData {
  id: string;
  type: "default" | "score-range" | "tag-match";
  /** Lower bound for score-range pages (inclusive). null means no lower bound. */
  minScore: number | null;
  /** Upper bound for score-range pages (inclusive). null means no upper bound. */
  maxScore: number | null;
  /** Tags required to match for tag-match pages (parsed from ResultPage.matchTags JSON). */
  matchTags: string[];
  /** Used for stable tiebreaking when multiple pages qualify. */
  position: number;
}

/**
 * The complete output of the scoring algorithm for one quiz submission.
 */
export interface ScoringResult {
  /** Sum of all answer scores (clamped to >= 0). */
  totalScore: number;
  /** Map of productTag -> number of times that tag appeared across all selected answers. */
  tagCounts: Record<string, number>;
  /** Tags sorted by count descending (alphabetical tiebreak). Top 10 by default. */
  topTags: string[];
  /** ID of the best-matching ResultPage, or null if no page matches. */
  matchedResultPageId: string | null;
  /** All selected tags sorted by frequency, for use as recommendation engine input. */
  recommendedProductTags: string[];
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Returns the numeric value encoded in a string field.
 * Returns 0 if the string is empty, null, undefined, or non-numeric.
 */
function parseNumericValue(value: string | undefined): number {
  if (value === undefined || value === null || value.trim() === "") return 0;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

/**
 * Collects all answer IDs referenced by a single QuizAnswer,
 * normalising single-select and multi-select into one array.
 */
function resolveAnswerIds(answer: QuizAnswer): string[] {
  if (answer.answerIds !== undefined && answer.answerIds.length > 0) {
    return answer.answerIds;
  }
  if (answer.answerId !== undefined && answer.answerId.trim() !== "") {
    return [answer.answerId];
  }
  return [];
}

// ── Exported pure functions ───────────────────────────────────────────────────

/**
 * Calculates the total numeric score across all submitted answers.
 *
 * - Single-choice (multiple-choice, image-choice, dropdown): adds answer.score.
 * - Multi-select (multiple-choice-multi): adds score for every selected answer.
 * - Slider / Rating: uses the raw numeric `value` field directly as the score.
 * - Text / Email / Date: contributes 0.
 *
 * The result is always >= 0. NaN is treated as 0.
 *
 * @param answers       The shopper's submitted answers.
 * @param answerDataMap Map of answerId -> AnswerData, pre-loaded from the DB.
 * @returns             Total score (integer >= 0).
 */
export function calculateScore(
  answers: QuizAnswer[],
  answerDataMap: Map<string, AnswerData>,
): number {
  if (answers.length === 0) return 0;

  let total = 0;

  for (const answer of answers) {
    const ids = resolveAnswerIds(answer);

    if (ids.length > 0) {
      // Choice-based question: sum DB scores for every selected answer ID.
      for (const id of ids) {
        const data = answerDataMap.get(id);
        if (data !== undefined) {
          const contribution = Number.isFinite(data.score) ? data.score : 0;
          total += contribution;
        }
      }
    } else if (answer.value !== undefined) {
      // Slider or rating: numeric value is the direct score contribution.
      total += parseNumericValue(answer.value);
    }
    // text-input, email, date: no answer IDs and value is a string that
    // should not be treated as numeric → contributes 0, which is the
    // default path when ids.length === 0 and value is non-numeric.
  }

  // Clamp to 0 — negative scores are not allowed.
  return Math.max(0, total);
}

/**
 * Builds a frequency map of product tags across all selected answers.
 *
 * Each time a tag appears on a selected answer it increments the count for
 * that tag by 1. For multi-select questions, all selected answers contribute
 * their tags independently.
 *
 * Tags are normalised to lowercase and trimmed before counting.
 * Empty strings are ignored.
 *
 * @param answers       The shopper's submitted answers.
 * @param answerDataMap Map of answerId -> AnswerData, pre-loaded from the DB.
 * @returns             Object mapping tag -> selection count.
 */
export function calculateTagCounts(
  answers: QuizAnswer[],
  answerDataMap: Map<string, AnswerData>,
): Record<string, number> {
  const counts: Record<string, number> = {};

  for (const answer of answers) {
    const ids = resolveAnswerIds(answer);
    for (const id of ids) {
      const data = answerDataMap.get(id);
      if (data === undefined) continue;
      for (const rawTag of data.productTags) {
        const tag = rawTag.toLowerCase().trim();
        if (tag === "") continue;
        counts[tag] = (counts[tag] ?? 0) + 1;
      }
    }
  }

  return counts;
}

/**
 * Sorts tags by selection count (descending) and returns the top N.
 *
 * Ties are broken alphabetically (ascending) so results are deterministic.
 *
 * @param tagCounts  Output of `calculateTagCounts`.
 * @param limit      Maximum tags to return (default 10). 0 = return all.
 * @returns          Sorted array of tag strings, most-selected first.
 */
export function getTopTags(
  tagCounts: Record<string, number>,
  limit: number = 10,
): string[] {
  const entries = Object.entries(tagCounts);
  if (entries.length === 0) return [];

  entries.sort(([tagA, countA], [tagB, countB]) => {
    if (countB !== countA) return countB - countA; // higher count first
    return tagA.localeCompare(tagB);               // alphabetical tiebreak
  });

  const effectiveLimit = limit > 0 ? limit : entries.length;
  return entries.slice(0, effectiveLimit).map(([tag]) => tag);
}

/**
 * Selects the best-matching ResultPage ID for the completed quiz.
 *
 * Matching priority (highest to lowest):
 *
 *  1. Score-range pages — find pages where `minScore <= totalScore <= maxScore`.
 *     - A null `minScore` is treated as -Infinity (no lower bound).
 *     - A null `maxScore` is treated as +Infinity (no upper bound).
 *     - If multiple score-range pages match, the one with the lowest `position`
 *       wins (most specific placement intended by the merchant).
 *
 *  2. Tag-match pages — find pages whose `matchTags` overlap with `topTags`.
 *     The page with the highest overlap count wins.
 *     Ties are broken by `position` (lowest wins).
 *
 *  3. Default page — the first `type === "default"` page ordered by position.
 *
 *  4. null — no result pages exist or none qualify.
 *
 * @param totalScore  Output of `calculateScore`.
 * @param topTags     Output of `getTopTags`.
 * @param resultPages All result pages for this quiz (any order).
 * @returns           The ID of the matched ResultPage, or null.
 */
export function matchResultPage(
  totalScore: number,
  topTags: string[],
  resultPages: ResultPageData[],
): string | null {
  if (resultPages.length === 0) return null;

  const topTagSet = new Set(topTags.map((t) => t.toLowerCase().trim()));

  // ── 1. Score-range matching ───────────────────────────────────────────────
  const scoreRangePages = resultPages
    .filter((page) => page.type === "score-range")
    .filter((page) => {
      const min = page.minScore ?? -Infinity;
      const max = page.maxScore ?? Infinity;
      return totalScore >= min && totalScore <= max;
    })
    .sort((a, b) => a.position - b.position);

  if (scoreRangePages.length > 0) {
    return scoreRangePages[0].id;
  }

  // ── 2. Tag-match matching ─────────────────────────────────────────────────
  const tagMatchPages = resultPages
    .filter((page) => page.type === "tag-match" && page.matchTags.length > 0)
    .map((page) => {
      const overlapCount = page.matchTags
        .map((t) => t.toLowerCase().trim())
        .filter((t) => topTagSet.has(t)).length;
      return { page, overlapCount };
    })
    .filter(({ overlapCount }) => overlapCount > 0)
    .sort((a, b) => {
      if (b.overlapCount !== a.overlapCount) return b.overlapCount - a.overlapCount;
      return a.page.position - b.page.position;
    });

  if (tagMatchPages.length > 0) {
    return tagMatchPages[0].page.id;
  }

  // ── 3. Default fallback ───────────────────────────────────────────────────
  const defaultPages = resultPages
    .filter((page) => page.type === "default")
    .sort((a, b) => a.position - b.position);

  if (defaultPages.length > 0) {
    return defaultPages[0].id;
  }

  return null;
}

/**
 * Returns a list of product tags ordered by selection frequency.
 *
 * This output feeds directly into the recommendation engine to query
 * `ProductMapping` records that share these tags.
 *
 * Tags with equal counts are sorted alphabetically for determinism.
 *
 * @param tagCounts  Output of `calculateTagCounts`.
 * @param limit      Maximum tags to return (default 20). 0 = return all.
 * @returns          Tags sorted most-selected first.
 */
export function getRecommendedProductTags(
  tagCounts: Record<string, number>,
  limit: number = 20,
): string[] {
  // Reuses getTopTags logic — just a different default limit and semantic intent.
  return getTopTags(tagCounts, limit);
}

/**
 * Master scoring function. Orchestrates all sub-functions and returns a
 * complete `ScoringResult` for storage and downstream use.
 *
 * This is the single entry point used by `api.quiz.$slug.submit.tsx`.
 *
 * @param answers       Shopper's submitted answers (from request body).
 * @param answerDataMap Answer DB records keyed by ID (pre-loaded, shop-scoped).
 * @param resultPages   All result pages for this quiz (pre-loaded).
 * @returns             Complete scoring result — ready to persist and render.
 */
export function calculateQuizResult(
  answers: QuizAnswer[],
  answerDataMap: Map<string, AnswerData>,
  resultPages: ResultPageData[],
): ScoringResult {
  const totalScore = calculateScore(answers, answerDataMap);
  const tagCounts = calculateTagCounts(answers, answerDataMap);
  const topTags = getTopTags(tagCounts, 10);
  const matchedResultPageId = matchResultPage(totalScore, topTags, resultPages);
  const recommendedProductTags = getRecommendedProductTags(tagCounts, 20);

  return {
    totalScore,
    tagCounts,
    topTags,
    matchedResultPageId,
    recommendedProductTags,
  };
}

