 1→/**
 2→ * scoring.ts — Score calculation helpers for the QuizSnap recommendation engine.
 3→ *
 4→ * All functions are pure (no I/O) and safe to import from server-side code.
 5→ * Tag comparisons are always case-insensitive (Architecture Law 6 / engine spec).
 6→ */
 7→
 8→/**
 9→ * Normalises a tag string to lowercase and trims whitespace so that
10→ * comparisons are always case-insensitive.
11→ */
12→export function normaliseTag(tag: string): string {
13→  return tag.toLowerCase().trim();
14→}
15→
16→/**
17→ * Normalises an array of tags.
18→ */
19→export function normaliseTags(tags: string[]): string[] {
20→  return tags.map(normaliseTag);
21→}
22→
23→/**
24→ * Given the quiz-accumulated tag counts (Record<tag, count>) and the set of
25→ * tags belonging to a single product, returns the aggregate relevance score
26→ * contributed purely by tag overlap.
27→ *
28→ * Each product tag that appears in `tagCounts` contributes its count value —
29→ * i.e. a tag chosen three times across different answers contributes 3, not 1.
30→ *
31→ * @param tagCounts  - Map of normalised tag → how many times it was selected
32→ * @param productTags - Normalised tags from the ProductMapping record
33→ * @returns { tagScore, matchedTags }
34→ */
35→export function computeTagScore(
36→  tagCounts: Record<string, number>,
37→  productTags: string[]
38→): { tagScore: number; matchedTags: string[] } {
39→  let tagScore = 0;
40→  const matchedTags: string[] = [];
41→
42→  for (const tag of productTags) {
43→    const count = tagCounts[normaliseTag(tag)];
44→    if (count !== undefined && count > 0) {
45→      tagScore += count;
46→      matchedTags.push(tag);
47→    }
48→  }
49→
50→  return { tagScore, matchedTags };
51→}
52→
53→/**
54→ * Calculates the final relevance score for a single product by combining the
55→ * tag-overlap score with the product's configured base score.
56→ *
57→ * Formula: relevanceScore = tagScore + baseScore
58→ *
59→ * @param tagScore  - Score from tag overlap (see computeTagScore)
60→ * @param baseScore - ProductMapping.score (merchant-configured weight)
61→ * @returns combined relevance score
62→ */
63→export function computeRelevanceScore(tagScore: number, baseScore: number): number {
64→  return tagScore + baseScore;
65→}
66→
67→/**
68→ * Converts a tagCounts record so every key is normalised (lowercase + trimmed).
69→ * Safe to call multiple times — idempotent.
70→ */
71→export function normaliseTagCounts(
72→  tagCounts: Record<string, number>
