255→      const max = page.maxScore ?? Infinity;
256→      return totalScore >= min && totalScore <= max;
257→    })
258→    .sort((a, b) => a.position - b.position);
259→
260→  if (scoreRangeMatches.length > 0) {
261→    return scoreRangeMatches[0].id;
262→  }
263→
264→  // ── 2. Tag-match matching ─────────────────────────────────────────────────
265→  type TagMatchCandidate = { page: ResultPageData; overlapCount: number };
266→
267→  const tagMatchCandidates: TagMatchCandidate[] = resultPages
268→    .filter((page) => page.type === "tag-match" && page.matchTags.length > 0)
269→    .map((page) => {
270→      const overlapCount = page.matchTags
271→        .map((t) => t.toLowerCase().trim())
272→        .filter((t) => topTagSet.has(t)).length;
273→      return { page, overlapCount };
274→    })
275→    .filter(({ overlapCount }) => overlapCount > 0)
276→    .sort((a, b) => {
277→      if (b.overlapCount !== a.overlapCount) return b.overlapCount - a.overlapCount;
278→      return a.page.position - b.page.position;
279→    });
280→
281→  if (tagMatchCandidates.length > 0) {
282→    return tagMatchCandidates[0].page.id;
283→  }
284→
285→  // ── 3. Default fallback ───────────────────────────────────────────────────
286→  const defaultMatches = resultPages
287→    .filter((page) => page.type === "default")
288→    .sort((a, b) => a.position - b.position);
289→
290→  if (defaultMatches.length > 0) {
291→    return defaultMatches[0].id;
292→  }
293→
294→  return null;
295→}
