315→/**
316→ * Master scoring function. Orchestrates all sub-functions and returns a
317→ * complete `ScoringResult` for storage and downstream use.
318→ *
319→ * This is the single entry point called by `api.quiz.$slug.submit.tsx`.
320→ * The caller must pre-load `answerDataMap` and `resultPages` from the DB,
321→ * scoped to the quiz and shop, before invoking this function.
322→ *
323→ * @param answers       Shopper's submitted answers (from request body).
324→ * @param answerDataMap Answer DB records keyed by ID (pre-loaded, shop-scoped).
325→ * @param resultPages   All result pages for this quiz (pre-loaded).
326→ * @returns             Complete scoring result — ready to persist and render.
327→ */
328→export function calculateQuizResult(
329→  answers: QuizAnswer[],
330→  answerDataMap: Map<string, AnswerData>,
331→  resultPages: ResultPageData[],
332→): ScoringResult {
333→  const totalScore = calculateScore(answers, answerDataMap);
334→  const tagCounts = calculateTagCounts(answers, answerDataMap);
335→  const topTags = getTopTags(tagCounts, 10);
336→  const matchedResultPageId = matchResultPage(totalScore, topTags, resultPages);
337→  const recommendedProductTags = getRecommendedProductTags(tagCounts, 20);
338→
339→  return {
340→    totalScore,
341→    tagCounts,
342→    topTags,
343→    matchedResultPageId,
344→    recommendedProductTags,
345→  };
346→}
