352→/**
353→ * Normalises a tag string to lowercase and trims whitespace so that
354→ * comparisons are always case-insensitive.
355→ */
356→export function normaliseTag(tag: string): string {
357→  return tag.toLowerCase().trim();
358→}
359→
360→/**
361→ * Normalises an array of tags.
362→ */
363→export function normaliseTags(tags: string[]): string[] {
364→  return tags.map(normaliseTag);
365→}
