367→/**
368→ * Given the quiz-accumulated tag counts (Record<tag, count>) and the set of
369→ * tags belonging to a single product, returns the aggregate relevance score
370→ * contributed purely by tag overlap.
371→ *
372→ * Each product tag that appears in `tagCounts` contributes its count value —
373→ * i.e. a tag chosen three times across different answers contributes 3, not 1.
374→ *
375→ * @param tagCounts   Map of normalised tag → how many times it was selected
376→ * @param productTags Normalised tags from the ProductMapping record
377→ * @returns { tagScore, matchedTags }
378→ */
379→export function computeTagScore(
380→  tagCounts: Record<string, number>,
381→  productTags: string[],
382→): { tagScore: number; matchedTags: string[] } {
383→  let tagScore = 0;
384→  const matchedTags: string[] = [];
385→
386→  for (const tag of productTags) {
387→    const count = tagCounts[normaliseTag(tag)];
388→    if (count !== undefined && count > 0) {
389→      tagScore += count;
390→      matchedTags.push(tag);
391→    }
392→  }
393→
394→  return { tagScore, matchedTags };
395→}
396→
397→/**
398→ * Calculates the final relevance score for a single product by combining the
399→ * tag-overlap score with the product's configured base score.
400→ *
401→ * Formula: relevanceScore = tagScore + baseScore
402→ *
403→ * @param tagScore  Score from tag overlap (see computeTagScore)
404→ * @param baseScore ProductMapping.score (merchant-configured weight)
405→ * @returns combined relevance score
406→ */
407→export function computeRelevanceScore(tagScore: number, baseScore: number): number {
408→  return tagScore + baseScore;
409→}
