411→/**
412→ * Converts a tagCounts record so every key is normalised (lowercase + trimmed).
413→ * Safe to call multiple times — idempotent.
414→ */
415→export function normaliseTagCounts(
416→  tagCounts: Record<string, number>,
417→): Record<string, number> {
418→  const result: Record<string, number> = {};
419→  for (const [tag, count] of Object.entries(tagCounts)) {
420→    const key = normaliseTag(tag);
421→    result[key] = (result[key] ?? 0) + count;
422→  }
423→  return result;
424→}
