426→/**
427→ * Checks whether all entries in `tagCounts` have a value of 0.
428→ * Used to detect the "no quiz answer selected any tags" edge case so the
429→ * recommendation engine can fall back to base-score ranking.
430→ */
431→export function isTagCountsEmpty(tagCounts: Record<string, number>): boolean {
432→  return Object.values(tagCounts).every((v) => v === 0);
